bool MetadataFields::validateJsonForCreation(const Json::Value &pJson, std::string &err)
{
    if(pJson.isMember("id"))
    {
        if(!validJsonOfField(0, "id", pJson["id"], err, true))
            return false;
    }
    if(pJson.isMember("field_name"))
    {
        if(!validJsonOfField(1, "field_name", pJson["field_name"], err, true))
            return false;
    }
    else
    {
        err="The field_name column cannot be null";
        return false;
    }
    if(pJson.isMember("field_label"))
    {
        if(!validJsonOfField(2, "field_label", pJson["field_label"], err, true))
            return false;
    }
    else
    {
        err="The field_label column cannot be null";
        return false;
    }
    if(pJson.isMember("field_type"))
    {
        if(!validJsonOfField(3, "field_type", pJson["field_type"], err, true))
            return false;
    }
    else
    {
        err="The field_type column cannot be null";
        return false;
    }
    if(pJson.isMember("field_group"))
    {
        if(!validJsonOfField(4, "field_group", pJson["field_group"], err, true))
            return false;
    }
    if(pJson.isMember("dropdown_options"))
    {
        if(!validJsonOfField(5, "dropdown_options", pJson["dropdown_options"], err, true))
            return false;
    }
    if(pJson.isMember("validation_rules"))
    {
        if(!validJsonOfField(6, "validation_rules", pJson["validation_rules"], err, true))
            return false;
    }
    if(pJson.isMember("is_required"))
    {
        if(!validJsonOfField(7, "is_required", pJson["is_required"], err, true))
            return false;
    }
    if(pJson.isMember("is_read_only"))
    {
        if(!validJsonOfField(8, "is_read_only", pJson["is_read_only"], err, true))
            return false;
    }
    if(pJson.isMember("is_searchable"))
    {
        if(!validJsonOfField(9, "is_searchable", pJson["is_searchable"], err, true))
            return false;
    }
    if(pJson.isMember("is_filterable"))
    {
        if(!validJsonOfField(10, "is_filterable", pJson["is_filterable"], err, true))
            return false;
    }
    if(pJson.isMember("include_in_csv"))
    {
        if(!validJsonOfField(11, "include_in_csv", pJson["include_in_csv"], err, true))
            return false;
    }
    if(pJson.isMember("exiftool_mapping"))
    {
        if(!validJsonOfField(12, "exiftool_mapping", pJson["exiftool_mapping"], err, true))
            return false;
    }
    if(pJson.isMember("display_order"))
    {
        if(!validJsonOfField(13, "display_order", pJson["display_order"], err, true))
            return false;
    }
    if(pJson.isMember("created_at"))
    {
        if(!validJsonOfField(14, "created_at", pJson["created_at"], err, true))
            return false;
    }
    if(pJson.isMember("modified_at"))
    {
        if(!validJsonOfField(15, "modified_at", pJson["modified_at"], err, true))
            return false;
    }
    return true;
}
